    private void open(YoutubeRepository.CollectionEntry e){if(e.kind.equals("playlist")){String url=PlaylistsActivity.playlistUrl(e.url);if(url!=null)startActivity(new Intent(this,PlaylistsActivity.class).putExtra("url",url));}else if(e.kind.equals("channel")){String url=ChannelUrls.parse(e.url);if(url!=null)startActivity(new Intent(this,MainActivity.class).putExtra("channel",url));}else{String id=VideoIds.parse(e.url);if(id!=null)startActivity(new Intent(this,PlayerActivity.class).putExtra("video",Video.link(id).json().toString()));}}
